enum {
  LEVEL_LAST = 32,
  BEACH_LAST = 25,
  MAP_LOC_LAST = 17,
  MAX_GOALS_PER_LEVEL = 5,
  MAX_BOARDS = 9,
  MAX_PHOTOS = 8,
  MAX_PREV_LEVELS = 4,
  NUM_EARNED_TRICKS_PER_SURFER = 14,
  NUM_LEARNED_TRICKS_PER_SURFER = 2,
  SURFER_LAST = 14,
  BEACH_INDOOR = 12
};

class CompressedPhoto {
  char data[0x2008];
public:
  void Reset();
};

class Career {
public:
  class Level {
    int my_id;
    bool is_new;
    bool advanced;
    bool unlocked;
    bool goals[MAX_GOALS_PER_LEVEL];
  public:
    void Reset();
    void SetMyId(int id) { my_id = id; }
    void Unlock();
  };

  class Beach {
    int my_id;
    bool unlocked;
    bool shown;
  public:
    void Reset();
    void SetMyId(int id) { my_id = id; }
    void Unlock();
  };

  class Location {
    int my_id;
    bool movie_unlocked;
    bool movie_shown;
    bool board_unlocked;
  public:
    void Reset();
    void SetMyId(int id) { my_id = id; }
  };

private:
  int spin, speed, jump, balance;
  int current_beach;
  int my_id;
  int my_board_id;
  char myInitials[4];
  int num_special_challenges_completed;
  bool using_personality_suit;
  int num_earned_tricks;
  bool learned_tricks[NUM_EARNED_TRICKS_PER_SURFER + NUM_LEARNED_TRICKS_PER_SURFER];
  bool new_goal_passed[MAX_GOALS_PER_LEVEL];
  bool goal_passed[MAX_GOALS_PER_LEVEL];
  bool boards[MAX_BOARDS];
  int totalStatPointsIncreased;
  CompressedPhoto compressedPhotos[MAX_PHOTOS];
  int levels_completed_order[LEVEL_LAST];
  int total_env_challenges;
  int env_challenges_passed;
  int super_board_was_unlocked;
  int espn_movie_was_unlocked;
  int bails_movie_was_unlocked;
  bool awarded[MAX_GOALS_PER_LEVEL];

public:
  Level levels[LEVEL_LAST];
  Beach beaches[BEACH_LAST];
  Location locations[MAP_LOC_LAST];

  void SetCurrentBeach(int beachIdx) { current_beach = beachIdx; }
  void StartNewCareer();
};

struct CareerData {
  int beach;
  char padding[0xa8];
  int prev_levels[MAX_PREV_LEVELS];
  char suffix[0x20];
};

extern CareerData CareerDataArray[];

__asm__(".equ CareerDataArray, 0x0042ECA0");
__asm__(".equ Reset__Q26Career5Level, 0x0025C340");
__asm__(".equ Unlock__Q26Career5Level, 0x0025C3A8");
__asm__(".equ Reset__Q26Career5Beach, 0x0025C4A0");
__asm__(".equ Unlock__Q26Career5Beach, 0x0025C4B0");
__asm__(".equ Reset__Q26Career8Location, 0x0025B918");
__asm__(".equ Reset__15CompressedPhoto, 0x00262A38");

void Career::StartNewCareer()
{
  int i, j, k;
  bool level_available;

  // So we know that it hasn't been set yet
  my_id = SURFER_LAST;
  my_board_id = 0;

  SetCurrentBeach(BEACH_INDOOR);


  for(i = 0; i < LEVEL_LAST; i++)
  {
    levels[i].SetMyId(i);
    levels[i].Reset();
  }
  for(i = 0; i < BEACH_LAST; i++)
  {
    beaches[i].SetMyId(i);
    //beaches[i].Reset();
  }
  for(i = 0; i < MAP_LOC_LAST; i++)
  {
    locations[i].SetMyId(i);
    //locations[i].Reset();
  }
  for(i = 0; i < MAX_BOARDS; i++)
  {
    boards[i] = false;
  }

  for (i = 0; i < MAX_PHOTOS; i++)
  {
    compressedPhotos[i].Reset ();
  }

  for(i = 0; i < MAP_LOC_LAST; i++)
  {
    locations[i].Reset();
  }

  // determine level availability, etc.
  for(j = 0; j < LEVEL_LAST; j++)
  {
    level_available = true;
    for(k = 0; k < MAX_PREV_LEVELS; k++)
      if(CareerDataArray[j].prev_levels[k] != -1)
        level_available = false;

      // If there were no previous levels then unlock this one
      if(level_available)
      {
        levels[j].Unlock(); // unlock the level
        beaches[CareerDataArray[j].beach].Unlock(); // and its associated beach
      }
  }

  num_special_challenges_completed = 0;
  num_earned_tricks = 0;
  using_personality_suit = false;
  for(i = 0; i < (NUM_LEARNED_TRICKS_PER_SURFER + NUM_EARNED_TRICKS_PER_SURFER); i++)
    learned_tricks[i] = false;

  // Clear out the environmental challenge counter
  env_challenges_passed = 0;
}
